"""Shared fixtures: the reference document generated by the cryptovault crate.

``tests/fixtures/rust_nofec.json`` is produced by ``interop/rust`` (subcommand
``fixtures``) from ``cryptovault`` 0.3.0 with ``NoFec``. Regenerate it with::

    cargo run --release --manifest-path interop/rust/Cargo.toml -- fixtures \
        > tests/fixtures/rust_nofec.json
"""

import functools
import json
import pathlib
from typing import Any

FIXTURE_DIR = pathlib.Path(__file__).parent / "fixtures"
FIXTURE_PATH = FIXTURE_DIR / "rust_nofec.json"
FEC_FIXTURE_PATH = FIXTURE_DIR / "rust_fec.json"


@functools.cache
def load_rust_fixtures() -> dict[str, Any]:
    """Load the crate-generated reference document, once per test session.

    Returns:
        The parsed JSON document.

    Raises:
        FileNotFoundError: If the fixture file has not been generated.
    """
    with FIXTURE_PATH.open(encoding="utf-8") as handle:
        document: dict[str, Any] = json.load(handle)
    return document


@functools.cache
def load_rust_fec_fixtures() -> dict[str, Any]:
    """Load the crate-generated FEC reference document, once per test session.

    Returns:
        The parsed JSON document.

    Raises:
        FileNotFoundError: If the fixture file has not been generated.
    """
    with FEC_FIXTURE_PATH.open(encoding="utf-8") as handle:
        document: dict[str, Any] = json.load(handle)
    return document
